import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * The {@code readFrom} method now creates a fresh {@link ParserOptions}
 * instance for each request and passes it directly to the parser.  This
 * guarantees that entity resolution is disabled before any XML is parsed,
 * eliminating the XXE risk that existed when the options were set on a
 * shared parser inside a synchronized block.
 *
 * By avoiding shared mutable parser state we also remove the need for
 * synchronization, improving concurrency without sacrificing security.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods ...

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a fresh parser instance from the Abdera engine.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options that explicitly disable entity resolution.
        // These options are not shared with other threads.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Critical: turn off external entity resolution to prevent XXE.
        options.setResolveEntities(false);
        // Additional hardening – ignore any DTD declarations if the parser
        // supports it (defensive programming; no effect if the method does not exist).
        try {
            options.getClass()
                   .getMethod("setIgnoreDTD", boolean.class)
                   .invoke(options, true);
        } catch (ReflectiveOperationException ignored) {
            // Method not present in this version of Abdera – safe to ignore.
        }

        // Parse the input using the securely configured options.
        Document<T> doc = parser.parse(entityStream, options);

        // Return the root element of the parsed Atom document.
        return doc.getRoot();
    }

    // other methods ...
}
