import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a file inside {@code dir} using the supplied {@code name}.
     * The method sanitises the {@code name} to prevent directory‑traversal
     * attacks and guarantees that the resulting file resides inside {@code dir}.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the original file name (may contain query part or path components)
     * @return a {@link File} that does not yet exist inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is invalid,
     *                                  or if the sanitised path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Remove any URL‑style query string (e.g. "file.txt?123")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Normalise the supplied name: keep only the last path segment
        // and reject any traversal attempts such as ".."
        // Convert Windows separators to '/' for uniform processing
        name = name.replace('\\', '/');
        // Split on '/' and take the last element (the actual file name)
        String[] parts = name.split("/");
        String fileName = parts[parts.length - 1];

        if (fileName.isEmpty()) {
            throw new IllegalArgumentException("File name resolves to an empty string");
        }
        if (fileName.contains("..")) {
            throw new IllegalArgumentException("Path traversal sequences are not allowed in file name");
        }

        // Build the initial File object
        File file = new File(dir, fileName);

        // Verify that the canonical path of the file is still inside the canonical
        // path of the target directory. This protects against any remaining tricks
        // such as symbolic‑link attacks.
        try {
            Path canonicalDir = dir.getCanonicalFile().toPath();
            Path canonicalFile = file.getCanonicalFile().toPath();

            if (!canonicalFile.startsWith(canonicalDir)) {
                throw new IllegalArgumentException(
                        "Resulting file would be outside the target directory");
            }
        } catch (IOException e) {
            // Wrap checked exception as unchecked – callers cannot recover from a
            // failure to resolve the canonical path.
            throw new IllegalArgumentException("Unable to resolve canonical path", e);
        }

        // Determine prefix / suffix for duplicate‑file handling
        int dot = fileName.lastIndexOf('.');
        String prefix = (dot < 0) ? fileName : fileName.substring(0, dot);
        String suffix = (dot < 0) ? "" : fileName.substring(dot);
        int index = 2;

        // If a file with the same name already exists, append a numeric suffix.
        while (file.exists()) {
            String candidateName = prefix + "-" + index++ + suffix;
            file = new File(dir, candidateName);
            try {
                // Re‑check the canonical path for each candidate
                Path canonicalCandidate = file.getCanonicalFile().toPath();
                if (!canonicalCandidate.startsWith(dir.getCanonicalFile().toPath())) {
                    throw new IllegalArgumentException(
                            "Resulting file would be outside the target directory");
                }
            } catch (IOException e) {
                throw new IllegalArgumentException("Unable to resolve canonical path", e);
            }
        }

        // Ensure the parent directory exists
        File parent = file.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalArgumentException("Failed to create directory structure for " + parent);
        }

        return file;
    }

    // other methods
}
