import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.logging.Logger;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;

/**
 * FactoryBean that creates a {@link SecureRandom} instance.
 *
 * <p>Previous implementations accepted an external seed via {@code Resource}
 * and called {@code SecureRandom#setSeed(byte[])}.  Supplying a predictable
 * seed undermines the cryptographic strength of the generator and can allow
 * attackers to predict future random values.  The factory now ignores any
 * externally‑provided seed and relies exclusively on the built‑in, platform‑
 * supplied entropy source.</p>
 *
 * <p>If the configured algorithm is unavailable, the factory falls back to
 * {@link SecureRandom#getInstanceStrong()} (Java 8) or the no‑arg constructor,
 * both of which perform secure, unpredictable seeding.</p>
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private static final Logger logger = Logger.getLogger(SecureRandomFactoryBean.class.getName());

    /** Preferred algorithm; may be {@code null} to let the platform choose. */
    private String algorithm = "SHA1PRNG";

    /** Optional external seed – retained for backward compatibility but ignored. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = createSecureRandomInstance();

        // -------------------------------------------------------------------
        // Do NOT use an externally supplied seed – it may be predictable.
        // -------------------------------------------------------------------
        if (seed != null) {
            logger.warning("SecureRandomFactoryBean: external seed resource is ignored to avoid predictability.");
        }

        // SecureRandom instances are automatically seeded; no further action required.
        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        // Each call returns a freshly‑initialized SecureRandom.
        return false;
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link SecureRandom} instance using the configured algorithm
     * if possible, otherwise falls back to the strongest available implementation.
     *
     * @return a securely seeded {@code SecureRandom}
     * @throws NoSuchAlgorithmException if the configured algorithm is not available
     */
    private SecureRandom createSecureRandomInstance() throws NoSuchAlgorithmException {
        SecureRandom rnd;
        if (algorithm != null && !algorithm.isEmpty()) {
            try {
                rnd = SecureRandom.getInstance(algorithm);
            } catch (NoSuchAlgorithmException e) {
                logger.warning("Algorithm '" + algorithm + "' not available; falling back to strong instance.");
                rnd = getStrongInstance();
            }
        } else {
            rnd = getStrongInstance();
        }
        return rnd;
    }

    /**
     * Returns a {@link SecureRandom} instance using {@code SecureRandom.getInstanceStrong()}
     * when available, otherwise the default constructor.
     *
     * @return a securely seeded {@code SecureRandom}
     */
    private SecureRandom getStrongInstance() {
        try {
            return SecureRandom.getInstanceStrong(); // Java 8+
        } catch (NoSuchAlgorithmException ex) {
            // Very unlikely, but the default constructor also provides a secure seed.
            logger.warning("Strong SecureRandom algorithm not available; using default constructor.");
            return new SecureRandom();
        }
    }

    // -----------------------------------------------------------------------
    // Setters for dependency injection (unchanged)
    // -----------------------------------------------------------------------

    public void setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
    }

    public void setSeed(Resource seed) {
        this.seed = seed;
    }
}
