protected void extractFile(final File srcF,
                           final File dir,
                           final InputStream compressedInputStream,
                           final String entryName,
                           final Date entryDate,
                           final boolean isDirectory,
                           final Integer mode,
                           String symlinkDestination) throws IOException, ArchiverException {

    if (entryName == null) {
        throw new ArchiverException("Entry name is null");
    }

    // Resolve the target file relative to the destination directory
    final File targetFile = FileUtils.resolveFile(dir, entryName);

    // ---- Zip‑Slip protection -------------------------------------------------
    // Resolve both paths to their canonical (real) form and compare them as
    // Path objects.  Using Path#startsWith prevents directory‑traversal attacks
    // such as "../" that would otherwise allow writing outside of {@code dir}.
    final Path canonicalDirPath = dir.getCanonicalFile().toPath();
    final Path canonicalTargetPath = targetFile.getCanonicalFile().toPath();

    if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
        throw new ArchiverException(
                "Entry is outside of the target directory (entry = " + entryName + ")");
    }

    // Do not allow a regular file entry to overwrite an existing symbolic link.
    if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTargetPath)) {
        throw new ArchiverException(
                "Refusing to overwrite existing symbolic link with regular file (entry = " + entryName + ")");
    }
    // -------------------------------------------------------------------------

    try {
        // Respect the overwrite flag and the timestamp of an existing file.
        if (!isOverwrite() && targetFile.exists()
                && targetFile.lastModified() >= entryDate.getTime()) {
            return;
        }

        // Ensure parent directories exist.
        final File parent = targetFile.getParentFile();
        if (parent != null) {
            parent.mkdirs();
        }

