        LOG.fine("Signature validation failed: " + e.getMessage());
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity", e);
    }
    // Verify reference URI
    List<Reference> refs = signature.getSignedInfo().getReferences();
    boolean found = false;
    for (Reference ref : refs) {
        String uri = ref.getURI();
        if (uri != null && (uri.equals("#" + elementId) || uri.isEmpty())) {
            found = true;
            break;
        }
    }
    if (!found) {
        LOG.fine("Signature does not reference expected element ID: " + elementId);
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
}

