/**
 * Extends the value {@code v} read from the JPEG bit‑stream to a signed integer.
 *
 * <p>The original implementation used a {@code while} loop that recomputed {@code vt}
 * on each iteration, which could never terminate for crafted inputs and caused a
 * potential denial‑of‑service. The JPEG specification defines this operation as a
 * simple conditional adjustment, not an iterative process.</p>
 *
 * @param v the raw value read (must be in the range [0, 2^t‑1])
 * @param t the number of bits used to encode {@code v} (must be between 1 and 31)
 * @return the correctly sign‑extended integer
 * @throws IllegalArgumentException if {@code t} is out of the allowed range or
 *         {@code v} is not a valid unsigned value for the given {@code t}
 */
private int extend(int v, final int t) {
    // Validate bit‑length – JPEG never uses more than 31 bits for a signed int.
    if (t <= 0 || t > 31) {
        throw new IllegalArgumentException("Bit length t must be between 1 and 31, got: " + t);
    }

    // Validate that v fits into t bits (unsigned interpretation).
    int maxUnsigned = (1 << t) - 1;
    if (v < 0 || v > maxUnsigned) {
        throw new IllegalArgumentException(
                "Value v is out of range for t bits: v=" + v + ", t=" + t);
    }

    // JPEG's extend operation: if the most‑significant bit is 0, adjust the value.
    int vt = 1 << (t - 1);               // 2^(t‑1)
    if (v < vt) {
        // (-1 << t) + 1 is equivalent to -(2^t) + 1, i.e. -(2^t - 1)
        v += (-1 << t) + 1;
    }
    return v;
}
