    public static String getContextPath(HttpServletRequest request) {
        // 1. Retrieve raw value – include attribute may be set by a dispatcher.
        String raw = (String) request.getAttribute(INCLUDE_CONTEXT_PATH_ATTRIBUTE);
        if (raw == null) {
