        CoderResult res = enc.encode(cb, out, false);
        if (res.isUnderflow()) {
            // all input consumed
            break;
        }
        if (res.isOverflow()) {
            // need more space for remaining input
            int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
            out = ZipEncodingHelper.growBufferBy(out, increment);
            continue;
        }
        // error (malformed or unmappable)
        if (res.isError()) {
            errorCount++;
            if (errorCount > MAX_ERROR_RETRIES) {
                // give up to avoid infinite loop
                throw new IllegalStateException("Too many encoding errors for input: " + name);
            }
            // ensure we have enough space for the replacement bytes (max 6 per char)
            int needed = estimateIncrementalEncodingSize(enc, 6 * res.length());
