            if (locale != null) {
                LOG.debug("Applied request locale: {}", locale);
            } else {
                LOG.warn("Locale parsing failed for valid string: [{}]; ignoring.", localeStr);
            }
            return locale;
        }

        // Any other object type is considered unsafe.
        LOG.warn("Unsupported locale parameter type: {}", requestedLocale.getClass().getName());
        return null;
