     * Creates an {@link LdapContext} using STARTTLS and performs an explicit bind
     * to verify the supplied credentials.  The method validates input, enforces TLS
     * negotiation, closes the {@link StartTlsResponse} and guarantees that an
     * authentication failure results in the context being closed.
     *
     * @param ldapContextFactory the factory that provides connection details
     * @param principal          the LDAP bind DN (must not be {@code null})
     * @param credentials        the password (must not be {@code null})
     * @return a fully bound {@link LdapContext}
     * @throws NamingException if any LDAP operation fails, including authentication
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                   Object principal,
                                                   Object credentials) throws NamingException {
        // ----- 1. Validate caller supplied credentials ---------------------------------
        if (principal == null) {
            throw new IllegalArgumentException("LDAP principal must not be null");
        }
        if (credentials == null) {
            throw new IllegalArgumentException("LDAP credentials must not be null");
        }

        // ----- 2. Build the initial (unencrypted) environment -------------------------
        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        LdapContext ctx = null;
        StartTlsResponse tls = null;

        try {
            // ----- 3. Create the raw context (no authentication yet) -----------------
            ctx = new InitialLdapContext(env, null);

            // ----- 4. Upgrade the connection to TLS ------------------------------------
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            // The default SSLContext performs proper certificate validation.
            tls.negotiate();

            // ----- 5. Inject security credentials after TLS is established -------------
            ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                                 jndiLdapContextFactory.getAuthenticationMechanism());
            ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
            ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

            // ----- 6. Force a bind to verify the credentials ---------------------------
            // A simple lookup on the empty name triggers the bind operation.
            ctx.lookup("");

            // If we reach this point the bind succeeded and the context is ready for use.
            return ctx;

        } catch (IOException e) {
            // ----- 7. TLS negotiation failure -----------------------------------------
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to negotiate TLS with LDAP server '%s': %s",
                                        server(jndiLdapContextFactory), e.getMessage()));
            throw new CommunicationException(e.getMessage(), e);

        } catch (NamingException ne) {
            // ----- 8. Authentication or other LDAP error ---------------------------------
            LdapUtils.closeContext(ctx);
            // Do NOT log the password; only the principal is safe to include.
            securityLog.warn(withRealm("LDAP authentication failed for principal '%s' on server '%s': %s",
                                       principal, server(jndiLdapContextFactory), ne.getMessage()));
            throw ne; // propagate the original NamingException (e.g., AuthenticationException)

        } finally {
            // ----- 9. Always close the TLS response to free resources --------------------
            if (tls != null) {
                try {
                    tls.close();
                } catch (IOException ignored) {
