/**
 * Securely creates a {@link Transformer} from an XSLT template stream.
 *
 * <p>This implementation mitigates XSLT injection attacks by:
 * <ul>
 *   <li>Enforcing {@code FEATURE_SECURE_PROCESSING} to limit processor capabilities.</li>
 *   <li>Disabling access to external DTDs and stylesheets via {@code ACCESS_EXTERNAL_DTD}
 *       and {@code ACCESS_EXTERNAL_STYLESHEET} attributes.</li>
 *   <li>Creating a fresh {@link TransformerFactory} per invocation to avoid
 *       cross‑thread side‑effects of mutable factory configuration.</li>
 *   <li>Validating the supplied {@link InputStream} and using try‑with‑resources
 *       to guarantee proper closure.</li>
 * </ul>
 *
 * @param templateStream an {@link InputStream} containing the XSLT template; must not be {@code null}
 * @return a configured {@link Transformer}
 * @throws IOException if an I/O error occurs while reading the stream
 * @throws ProcessingFailedException if the XSLT cannot be compiled
 */
private static Transformer createTransformer(InputStream templateStream) throws IOException {
    if (templateStream == null) {
        throw new IllegalArgumentException("templateStream must not be null");
    }

    // Create a new factory for each call to avoid shared mutable state.
    TransformerFactory factory = TransformerFactory.newInstance();

    // Enable secure processing – limits the use of extensions and other risky features.
    try {
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
    } catch (TransformerConfigurationException e) {
        // If the implementation does not support the feature, fail fast.
        throw new ProcessingFailedException("Secure processing feature not supported", e);
    }

    // Restrict any external entity or stylesheet access.
    try {
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
    } catch (IllegalArgumentException e) {
        // Some factories may not support these attributes; treat it as a configuration error.
        throw new ProcessingFailedException("Factory does not support external access restrictions", e);
    }

    // Compile the XSLT template.
    try (InputStream is = templateStream) {
        StreamSource source = new StreamSource(is);
        return factory.newTransformer(source);
    } catch (TransformerConfigurationException e) {
        throw new ProcessingFailedException("Failed to create XSLT template", e);
    }
}
