/**
 * Implementation of read for STORED entries.
 *
 * This method has been hardened to correctly detect end‑of‑file conditions.
 * It now:
 * <ul>
 *   <li>Handles entries with an unknown size (csize &lt; 0) by relying on the
 *       underlying stream’s EOF.</li>
 *   <li>Treats a non‑positive read from the underlying stream as EOF to avoid
 *       infinite loops with streams that may return 0 bytes.</li>
 *   <li>Ensures that we never read past the declared size of the entry.</li>
 *   <li>Uses {@link ByteBuffer#hasRemaining()} for clarity and resets the
 *       buffer safely with {@link ByteBuffer#clear()}.</li>
 * </ul>
 */
private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // If the entry uses a data descriptor we have already cached the whole
    // entry in a ByteArrayInputStream.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();               // fills lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    // Size of the entry as reported in the ZIP header (may be -1 if unknown)
    final long csize = current.entry.getSize();

    // If we know the size and have already read it all, signal EOF.
    if (csize >= 0 && current.bytesRead >= csize) {
        return -1;
    }

    // Fill the internal buffer when it is exhausted.
    if (!buf.hasRemaining()) {
        // Reset buffer for a fresh read.
        buf.clear();                         // position = 0, limit = capacity
        final int bytesRead = in.read(buf.array());
        // A return value of -1 (EOF) or 0 (no progress) must be treated as EOF
        // to prevent an infinite read loop on misbehaving streams.
        if (bytesRead <= 0) {
            return -1;
        }
        buf.limit(bytesRead);
        count(bytesRead);
        current.bytesReadFromStream += bytesRead;
    }

    // Determine the maximum number of bytes we can return this call.
    int toRead = Math.min(buf.remaining(), length);
    if (csize >= 0) {
        long remainingInEntry = csize - current.bytesRead;
        if (remainingInEntry <= 0) {
            return -1;                       // safety net – should not happen
        }
        if (remainingInEntry < toRead) {
            toRead = (int) remainingInEntry;
        }
    }

    // Transfer bytes from the internal buffer to the caller's buffer.
    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
