    /**
     * Creates a securely configured {@link XMLStreamReader}.
     *
     * <p>This method disables DTD processing and external entity resolution to
     * protect against XML External Entity (XXE) attacks.  The configuration
     * steps are wrapped in try/catch blocks because some {@link XMLInputFactory}
     * implementations may not support the corresponding properties; in such
     * cases the exception is ignored and the factory proceeds with the safest
     * possible configuration.</p>
     *
     * @param inputStream the raw XML input stream
     * @return a configured {@link XMLStreamReader}
     * @throws XMLStreamException if the underlying parser cannot be created
     * @throws IOException        if an I/O error occurs while wrapping the stream
     */
    private static final XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {

        XMLInputFactory factory = XMLInputFactory.newInstance();

        /* -------------------------------------------------------------
         * Harden the factory against XXE attacks
         * ------------------------------------------------------------- */
        try {
            // Disallow DTDs (which are the entry point for external entities)
            factory.setProperty(XMLInputFactory.SUPPORT_DTD, Boolean.FALSE);
        } catch (IllegalArgumentException | IllegalStateException ignored) {
            // Property not supported – the factory will behave as securely as possible
        }

        try {
            // Prevent the parser from resolving external entities
            factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
        } catch (IllegalArgumentException | IllegalStateException ignored) {
            // Property not supported – continue with the safest configuration
        }

        /* -------------------------------------------------------------
         * Retain the original, safe defaults used by the application
         * ------------------------------------------------------------- */
        factory.setProperty(XMLInputFactory.IS_COALESCING, Boolean.TRUE);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, Boolean.TRUE);

        // Ensure namespace awareness – optional but recommended for XML 1.0 documents
        try {
            factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, Boolean.TRUE);
        } catch (IllegalArgumentException | IllegalStateException ignored) {
            // Not all factories expose this property; ignore if unavailable
        }

        // The original code wrapped the stream to strip a possible XML prefix.
        // Preserve that behaviour.
        return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
    }

